-- ============================================================================
-- IE→ES (Dublin→Madrid) corridor requirements — 25 verified records.
--
-- Source of truth: corridors/IE_ES/data/ie_es_requirement_facts.ndjson
-- (sha256 verified against corridors/IE_ES/data/manifest.json).
-- GENERATED by scripts/gen_ie_es_corridor_load.py — regenerate, do not hand-edit.
--
-- TARGET: public.requirement_items, NOT public.requirement_facts. The batch manifest
-- names requirement_facts keyed on fact_uid, but that table has no fact_uid column and
-- two NOT NULL uuid FKs (entity_id, source_doc_id) the NDJSON cannot supply. Its `id` is
-- varchar, so it carries the fact_uid verbatim and the upsert key is preserved exactly.
-- requirement_items is also what the deterministic engine reads, so this is the only
-- landing that makes the corridor servable.
--
-- review_status='pending' is EXPLICIT. The column defaults to 'approved' and
-- requirements_builder serves only approved rows, so a plain INSERT would publish 25
-- unreviewed REPRESENTATIVE facts to real users on apply. They reach a customer only
-- after a human approves them.
--
-- Idempotent: ON CONFLICT (id) DO UPDATE. Re-running yields 25 rows, never 50.
-- The update deliberately does NOT touch review_status, reviewed_by or reviewed_at —
-- re-running a load must not un-approve what a reviewer has since approved.
-- ============================================================================

INSERT INTO public.requirement_items
    (id, country_code, purpose, pillar, title, description, severity, owner, required_fields_json, citations_json, applies_to_nationality_classes_json, non_obvious, verification_status, review_status, last_verified_at)
VALUES
    ('ES:IE-ES:registration_certificado_registro_ue', 'SPAIN', 'employment', 'RESIDENCE', 'Registration certificado registro ue', 'EU citizens (including Irish nationals) who intend to reside in Spain for more than 3 months must register in person in the Registro Central de Extranjeros and obtain the Certificado de Registro de Ciudadano de la Unión (the ''green certificate''), applied for at an Oficina de Extranjería or Comisaría de Policía Nacional with prior appointment (cita previa).

Why this is easy to miss: This certificate is NOT a residence permit/card and NOT a TIE — it is a small green paper/card-sized document, contains no photo, and is easily lost; keep the original safe as it is the primary proof of legal residence.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://sede.policia.gob.es/portalCiudadano/_es/tramites_extranjeria_tramite_certificadoregistro_ciudadanoue.php", "name": "Sede Electrónica de la Policía Nacional (Ministerio del Interior)", "corridor": "IE-ES", "topic_key": "registration_certificado_registro_ue", "domain_area": "registration"}]', '["EU_EEA"]', TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:registration_ex18_form_fee', 'SPAIN', 'employment', 'RESIDENCE', 'Registration ex18 form fee', 'The application for the EU registration certificate is made on official form EX-18, and the fee (tasa modelo 790, código 012, ~€12) must be paid before the appointment with the payment receipt presented at the appointment.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.inclusion.gob.es/web/migraciones/w/65.-certificado-de-registro-de-ciudadano-de-la-union-europea", "name": "Ministerio de Inclusión, Seguridad Social y Migraciones", "corridor": "IE-ES", "topic_key": "registration_ex18_form_fee", "domain_area": "registration"}]', '["EU_EEA"]', FALSE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:registration_economic_means_proof', 'SPAIN', 'employment', 'RESIDENCE', 'Registration economic means proof', 'To register, an EU citizen must document their basis of residence: workers show an employment contract or Social Security affiliation; non-workers must prove sufficient economic means for themselves and family plus comprehensive private/public health insurance.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.interior.gob.es/opencms/es/servicios-al-ciudadano/tramites-y-gestiones/extranjeria/ciudadanos-de-la-union-europea/residencia-de-caracter-permanente/", "name": "Ministerio del Interior — Extranjería (ciudadanos de la Unión Europea)", "corridor": "IE-ES", "topic_key": "registration_economic_means_proof", "domain_area": "registration"}]', '["EU_EEA"]', FALSE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:registration_nie_number', 'SPAIN', 'employment', 'IDENTITY', 'Registration nie number', 'The NIE (Número de Identidad de Extranjero) is the personal foreign-national ID number required for tax, work, banking and property; for an EU citizen it is assigned as part of the registration certificate (the green certificate shows the NIE). A standalone NIE can be requested via form EX-15.

Why this is easy to miss: Holding a NIE alone does not grant the right to reside — the green registration certificate is the document that proves residence; the two are often confused.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.interior.gob.es/opencms/es/servicios-al-ciudadano/tramites-y-gestiones/extranjeria/ciudadanos-de-la-union-europea/numero-de-Identidad-de-extranjero-nie/", "name": "Ministerio del Interior — Número de Identidad de Extranjero (NIE)", "corridor": "IE-ES", "topic_key": "registration_nie_number", "domain_area": "registration"}]', '["EU_EEA"]', TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:registration_cita_previa_bottleneck', 'SPAIN', 'employment', 'RESIDENCE', 'Registration cita previa bottleneck', 'Registration and NIE procedures require a prior appointment (cita previa) booked through the Sede Electrónica; in Madrid appointment slots for Extranjería/Policía are a well-known bottleneck and can be scarce, so booking early is essential to avoid delaying the whole move.

Why this is easy to miss: The cita-previa scarcity is a scheduling trap: an employee can arrive legally but be unable to complete registration for weeks, blocking downstream steps (bank, healthcare card) that depend on it.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://sede.policia.gob.es/portalCiudadano/_es/tramites_extranjeria_tramite_asignacion_nie.php", "name": "Sede Electrónica de la Policía Nacional", "corridor": "IE-ES", "topic_key": "registration_cita_previa_bottleneck", "domain_area": "registration"}]', '["EU_EEA"]', TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:registration_tie_only_for_non_eu', 'SPAIN', 'employment', 'RESIDENCE', 'Registration tie only for non eu', 'The Tarjeta de Identidad de Extranjero (TIE) card applies to non-EU third-country nationals (e.g. non-EU family members or a non-EU employee relocating from Dublin), NOT to EU citizens — EU citizens receive the green Certificado de Registro instead.

Why this is easy to miss: If the person moving from Ireland is a non-EU national (with Irish residence), they follow a different track (residence authorisation + TIE), not the EU green-certificate track — a critical branching point to establish before any paperwork starts.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://sede.policia.gob.es/portalCiudadano/_es/tramites_extranjeria_tramite_certificadoregistro_ciudadanoue.php", "name": "Sede Electrónica de la Policía Nacional", "corridor": "IE-ES", "topic_key": "registration_tie_only_for_non_eu", "domain_area": "immigration"}]', '["EU_EEA"]', TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:empadronamiento_padron_municipal', 'SPAIN', 'employment', 'RESIDENCE', 'Empadronamiento padron municipal', 'New residents must register their address on the Padrón Municipal (empadronamiento) at their Ayuntamiento; in Madrid this is done at the Padrón/Junta de Distrito or online with Cl@ve/certificado digital, and yields the certificado/volante de empadronamiento.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://sede.madrid.es/portal/site/tramites/menuitem.62876cb64654a55e2dbd7003a8a409a0/?vgnextoid=3e3debb41f6e2410VgnVCM2000000c205a0aRCRD&vgnextchannel=775ba38813180210VgnVCM100000c90da8c0RCRD&vgnextfmt=default", "name": "Ayuntamiento de Madrid — Sede Electrónica (Padrón Municipal)", "corridor": "IE-ES", "topic_key": "empadronamiento_padron_municipal", "domain_area": "registration"}]', NULL, FALSE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:empadronamiento_documents', 'SPAIN', 'employment', 'RESIDENCE', 'Empadronamiento documents', 'Empadronamiento in Madrid requires the hoja padronal (registration form), a valid ID (passport or NIE document) for each person, and proof of address (rental contract/escritura, or an authorisation from the registered occupant); minors need libro de familia or birth certificate.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://sede.madrid.es/portal/site/tramites/menuitem.62876cb64654a55e2dbd7003a8a409a0/?vgnextoid=3e3debb41f6e2410VgnVCM2000000c205a0aRCRD&vgnextchannel=775ba38813180210VgnVCM100000c90da8c0RCRD&vgnextfmt=default", "name": "Ayuntamiento de Madrid — Sede Electrónica (Padrón Municipal)", "corridor": "IE-ES", "topic_key": "empadronamiento_documents", "domain_area": "registration"}]', NULL, FALSE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:empadronamiento_dependency_chain', 'SPAIN', 'employment', 'RESIDENCE', 'Empadronamiento dependency chain', 'The empadronamiento (certificado de empadronamiento) is a prerequisite for the public healthcare card (tarjeta sanitaria), school enrolment, and driving-licence exchange, so it should be completed as early as possible after securing an address.

Why this is easy to miss: Empadronamiento is an invisible gating dependency: several later steps silently require it, so skipping or delaying it stalls healthcare and other essential services even though nothing ''asks'' for it up front.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "http://sede.comunidad.madrid/node/216763", "name": "Comunidad de Madrid — Sede Electrónica (Tarjeta Sanitaria)", "corridor": "IE-ES", "topic_key": "empadronamiento_dependency_chain", "domain_area": "registration"}]', NULL, TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:tax_residency_183_days', 'SPAIN', 'employment', 'EMPLOYMENT', 'Tax residency 183 days', 'An individual becomes a Spanish tax resident (taxed on worldwide income under IRPF) if they spend more than 183 days in the calendar year in Spain, or if their main centre of economic interests is in Spain; residence for a full tax year is triggered once the 183-day threshold is met.

Why this is easy to miss: Spain has no split-year concept for the 183-day test: crossing 183 days makes you resident for the WHOLE calendar year retroactively, which can pull worldwide income earned before the move into Spanish tax.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://sede.agenciatributaria.gob.es/Sede/no-residentes/residencia-personas-fisicas-juridicas/persona-fisica-residente-espana.html", "name": "Agencia Tributaria (AEAT) — Persona física residente en España", "corridor": "IE-ES", "topic_key": "tax_residency_183_days", "domain_area": "tax", "needs_lawyer_review": true, "review_reason": "Claim concerns the Ireland–Spain double taxation treaty tie-breaker but is sourced to the AEAT residency page, not the treaty text."}]', NULL, TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:tax_modelo_030_alta', 'SPAIN', 'employment', 'EMPLOYMENT', 'Tax modelo 030 alta', 'New residents communicate their tax status, fiscal address and personal-data changes to the Agencia Tributaria using Modelo 030 (declaración censal de alta/variación en el censo de obligados tributarios).', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://sede.agenciatributaria.gob.es/Sede/censos-nif-domicilio-fiscal/censos/modelo-030-censo_____de-domicilio-variacion-personales_/instrucciones.html", "name": "Agencia Tributaria (AEAT) — Modelo 030 (instrucciones)", "corridor": "IE-ES", "topic_key": "tax_modelo_030_alta", "domain_area": "tax"}]', NULL, FALSE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:tax_beckham_regime', 'SPAIN', 'employment', 'EMPLOYMENT', 'Tax beckham regime', 'Impatriate employees may opt into the special regime for workers posted to Spanish territory (''Ley Beckham''), taxed as non-residents at a flat 24% (up to €600k) for up to 6 years; the option is communicated via Modelo 149 within 6 months of Social Security registration (alta).

Why this is easy to miss: The 6-month Modelo 149 window runs from Social Security alta and is strict: missing it forfeits a materially lower (24% flat) tax rate for the whole assignment — a high-value deadline most first-time HR movers do not know exists.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://sede.agenciatributaria.gob.es/Sede/procedimientoini/G606.shtml", "name": "Agencia Tributaria (AEAT) — Modelo 149, régimen especial de trabajadores desplazados", "corridor": "IE-ES", "topic_key": "tax_beckham_regime", "domain_area": "tax"}]', NULL, TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:tax_ie_es_double_taxation', 'SPAIN', 'employment', 'EMPLOYMENT', 'Tax ie es double taxation', 'Whether Ireland or Spain taxes specific income in the year of the move is governed by the Ireland-Spain double taxation convention and the tax-residency tie-breaker rules; relief mechanisms prevent the same income being taxed twice.

Why this is easy to miss: In the transition year the employee can be treated as resident by both Ireland and Spain; the treaty tie-breaker (permanent home, centre of vital interests) — not the calendar — decides, so professional review is warranted for the move year.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://sede.agenciatributaria.gob.es/Sede/no-residentes/residencia-personas-fisicas-juridicas/persona-fisica-residente-espana.html", "name": "Agencia Tributaria (AEAT) — residencia fiscal (residentes/no residentes)", "corridor": "IE-ES", "topic_key": "tax_ie_es_double_taxation", "domain_area": "tax", "needs_lawyer_review": true, "review_reason": "Claim concerns the Ireland–Spain double taxation treaty tie-breaker but is sourced to the AEAT residency page, not the treaty text."}]', NULL, TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:social_security_single_state_rule', 'SPAIN', 'employment', 'SOCIAL_SECURITY', 'Social security single state rule', 'Under EU social-security coordination (Regulation 883/2004) a worker is covered by only one country''s system at a time — as a general rule the country where they physically work — so an employee working in Spain is normally covered by, and contributes to, the Spanish Seguridad Social.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://europa.eu/youreurope/citizens/work/social-security-and-benefits/country-coverage/index_en.htm", "name": "Your Europe (European Commission) — social security coverage", "corridor": "IE-ES", "topic_key": "social_security_single_state_rule", "domain_area": "social_security"}]', NULL, FALSE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:social_security_a1_posted_worker', 'SPAIN', 'employment', 'SOCIAL_SECURITY', 'Social security a1 posted worker', 'If the employee stays employed by the Irish employer and is posted temporarily (generally up to 24 months), a PD A1 certificate issued in Ireland keeps them in the Irish social-security system and exempts them from Spanish contributions for that period.

Why this is easy to miss: The A1 must be requested from the HOME country''s authority (Ireland) BEFORE or at the start of the posting; without it Spain can demand local contributions, causing costly double social-security payments.', 'WARN', 'EMPLOYER', '[]', '[{"url": "https://europa.eu/youreurope/business/hiring-managing-staff/cross-border-posted-workers/posting-staff-abroad/index_en.htm", "name": "Your Europe (European Commission) — posting staff abroad / PD A1", "corridor": "IE-ES", "topic_key": "social_security_a1_posted_worker", "domain_area": "social_security"}]', NULL, TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:social_security_nuss_afiliacion', 'SPAIN', 'employment', 'SOCIAL_SECURITY', 'Social security nuss afiliacion', 'To work in Spain the employee needs a Número de la Seguridad Social (NUSS, also NAF); the employer must register the worker''s alta with the Seguridad Social before the start of work, and the individual can request the NUSS via the Importass portal / model TA.1.

Why this is easy to miss: The NIE is not a social-security or health number: NUSS (Seguridad Social) and the later TSI (health card) are separate numbers/steps, so having a NIE does not by itself give payroll or medical access.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://portal.seg-social.gob.es/wps/portal/importass/importass/Categorias/Altas%2C+bajas+y+modificaciones/Altas+y+afiliacion+de+trabajadores/Solicitar+el+numero+de+la+Seguridad+Social", "name": "Seguridad Social — Importass (Solicitar el número de la Seguridad Social)", "corridor": "IE-ES", "topic_key": "social_security_nuss_afiliacion", "domain_area": "social_security"}]', NULL, TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:social_security_employer_alta', 'SPAIN', 'employment', 'SOCIAL_SECURITY', 'Social security employer alta', 'The Spanish employer is responsible for registering the employee (alta) in the Seguridad Social, which requires the employee to already hold a NUSS; this alta date is also the trigger for the 6-month Beckham-regime election deadline.', 'INFO', 'EMPLOYER', '[]', '[{"url": "https://administracion.gob.es/pag_Home/Tu-espacio-europeo/derechos-obligaciones/empresas/empleados/seguridad-social/alta-empleados.html", "name": "Punto de Acceso General (administracion.gob.es) — alta de empleados en Seguridad Social", "corridor": "IE-ES", "topic_key": "social_security_employer_alta", "domain_area": "social_security"}]', NULL, FALSE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:healthcare_sns_tsi', 'SPAIN', 'employment', 'HEALTHCARE', 'Healthcare sns tsi', 'Public healthcare is accessed through the Sistema Nacional de Salud; a resident obtains the Tarjeta Sanitaria Individual (TSI) from the assigned centro de salud in the Comunidad de Madrid, which registers them with a GP and gives access to public health services.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.comunidad.madrid/salud/tarjeta-sanitaria", "name": "Comunidad de Madrid — Tarjeta Sanitaria", "corridor": "IE-ES", "topic_key": "healthcare_sns_tsi", "domain_area": "healthcare"}]', NULL, FALSE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:healthcare_tsi_requirements', 'SPAIN', 'employment', 'HEALTHCARE', 'Healthcare tsi requirements', 'To obtain the Madrid TSI the applicant must be empadronado in the Comunidad de Madrid AND have the right to healthcare recognised by the INSS (typically through employment/Social Security affiliation).

Why this is easy to miss: The TSI has a two-part gate — empadronamiento AND INSS-recognised healthcare right — so an employee who is registered at their address but whose Social Security alta is not yet processed still cannot get the health card.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "http://sede.comunidad.madrid/node/216763", "name": "Comunidad de Madrid — Sede Electrónica (requisitos Tarjeta Sanitaria)", "corridor": "IE-ES", "topic_key": "healthcare_tsi_requirements", "domain_area": "healthcare"}]', NULL, TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:healthcare_ehic_transition', 'SPAIN', 'employment', 'HEALTHCARE', 'Healthcare ehic transition', 'Before the TSI is issued, an Irish EHIC covers only temporary/necessary care and is not a substitute for enrolling in the Spanish system as a resident; residents must complete SNS enrolment for ongoing care.

Why this is easy to miss: Relying on the EHIC after becoming resident is a common trap: it does not cover routine/ongoing treatment, leaving a coverage gap until the TSI comes through.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://europa.eu/youreurope/citizens/work/social-security-and-benefits/country-coverage/index_en.htm", "name": "Your Europe (European Commission) — healthcare cover when moving", "corridor": "IE-ES", "topic_key": "healthcare_ehic_transition", "domain_area": "healthcare"}]', NULL, TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:housing_fianza_deposit', 'SPAIN', 'employment', 'HOUSING', 'Housing fianza deposit', 'Residential leases under the Ley de Arrendamientos Urbanos (LAU) require a legal security deposit (fianza) of one month''s rent for housing; in practice Madrid landlords frequently ask for additional guarantees (extra months or an aval bancario), especially from newcomers without local history.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.mivau.gob.es/vivienda/alquila-bien-es-tu-derecho/alquiler/deposito-de-fianzas", "name": "Ministerio de Vivienda y Agenda Urbana (MIVAU) — depósito de fianzas", "corridor": "IE-ES", "topic_key": "housing_fianza_deposit", "domain_area": "housing"}]', NULL, FALSE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:housing_fianza_regional_deposit', 'SPAIN', 'employment', 'HOUSING', 'Housing fianza regional deposit', 'The obligation and body for depositing the fianza vary by autonomous community; where required the landlord must lodge the deposit with the regional housing authority, so tenants should confirm the deposit is correctly registered.

Why this is easy to miss: Deposit rules are regional, not national, so guidance found for another region may not apply in Madrid — verify the Comunidad de Madrid procedure specifically.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.mivau.gob.es/vivienda/alquila-bien-es-tu-derecho/alquiler/deposito-de-fianzas", "name": "Ministerio de Vivienda y Agenda Urbana (MIVAU) — depósito de fianzas", "corridor": "IE-ES", "topic_key": "housing_fianza_regional_deposit", "domain_area": "housing"}]', NULL, TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:housing_nie_needed_to_rent', 'SPAIN', 'employment', 'HOUSING', 'Housing nie needed to rent', 'In practice a NIE (and usually a Spanish bank account plus a local nómina/payslip) is needed to sign a lease and set up utilities, creating a chicken-and-egg with registration since empadronamiento itself typically needs a rental contract.

Why this is easy to miss: The NIE ↔ housing ↔ empadronamiento sequence is circular: landlords want a NIE, empadronamiento wants an address, and the certificate wants proof of residence — plan a workable order (often NIE first, then lease, then padrón).', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://www.interior.gob.es/opencms/es/servicios-al-ciudadano/tramites-y-gestiones/extranjeria/ciudadanos-de-la-union-europea/numero-de-Identidad-de-extranjero-nie/", "name": "Ministerio del Interior — NIE", "corridor": "IE-ES", "topic_key": "housing_nie_needed_to_rent", "domain_area": "housing"}]', NULL, TRUE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:driving_eu_licence_valid', 'SPAIN', 'employment', 'IDENTITY', 'Driving eu licence valid', 'An Irish/EU driving licence remains valid for driving in Spain; exchanging (canje) it for a Spanish permit is voluntary for EU/EEA licences and not required to keep driving while the licence is in force.', 'INFO', 'EMPLOYEE', '[]', '[{"url": "https://www.dgt.es/nuestros-servicios/permisos-de-conducir/cambio-de-domicilio/vienes-a-vivir-a-espana/trasladarte-a-espana-desde-un-pais-de-la-union-europea/", "name": "Dirección General de Tráfico (DGT) — trasladarte a España desde la UE", "corridor": "IE-ES", "topic_key": "driving_eu_licence_valid", "domain_area": "other"}]', NULL, FALSE, 'representative', 'pending', NOW()),
    ('ES:IE-ES:driving_dgt_registration', 'SPAIN', 'employment', 'IDENTITY', 'Driving dgt registration', 'EU/EEA licence holders resident in Spain can register or exchange their licence with the DGT (voluntary canje) and, for certain licence conditions/renewals, may need to register their data with the DGT; check DGT requirements after establishing residence.

Why this is easy to miss: Although driving is allowed on the Irish licence, renewals while resident in Spain can require DGT registration/exchange, so long-stay employees should not assume the licence is fully self-sufficient indefinitely.', 'WARN', 'EMPLOYEE', '[]', '[{"url": "https://sede.dgt.gob.es/es/permisos-de-conducir/canjes-de-permisos/canjes-de-permisos-extranjeros/canjes-inscripcion-renovacion-y-sustitucion-de-permisos-de-la-ue-y-eee/canje-de-permisos-de-la-ue-y-eee/", "name": "Sede Electrónica de la DGT — canje de permisos UE/EEE", "corridor": "IE-ES", "topic_key": "driving_dgt_registration", "domain_area": "other"}]', NULL, TRUE, 'representative', 'pending', NOW())
